//! Cargo-driven `kernelbase.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMain@12", None),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMain", None),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMain", None),
        o => panic!("kernelbase-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["import:kernel32", "import:ntdll_vista", "import:ntdll"],
        "x86_64" => &["import:kernel32", "import:ntdll_vista", "import:ntdll"],
        "aarch64" => &["import:kernel32", "import:ntdll_vista", "import:ntdll"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/kernelbase",
        "dll/win32/kernelbase",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/lib/pseh/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &["WINVER=0x600", "_WIN32_WINNT=0x600"];

    Linker::new(target_json)
        .c_from_compile_db("kernelbase_shims", &["dll/win32/kernelbase/dllmain.c"])
        .rc("dll/win32/kernelbase/kernelbase.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/kernelbase/kernelbase.spec", "kernelbase.dll")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/nt_0600/ntdll_vista.spec", "ntdll_vista.dll", "ntdll_vista")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
